#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_MEMO_LEN 256
#define MAX_HEADER_LEN 512
#define PROXY_HEADER_PREFIX "X-Contract-"

typedef struct {
    uint64_t sender;
    uint64_t receiver;
    uint64_t amount;
    char memo[MAX_MEMO_LEN];
    uint8_t memo_len;
} Transaction;

typedef struct {
    char headers[MAX_HEADER_LEN];
    int headers_len;
    char body[1024];
    int body_len;
} ProxyResponse;

/* Encoding table for contract memo field - allows printable ASCII */
static int is_memo_printable(unsigned char c) {
    return (c >= 0x20 && c <= 0x7E);
}

/* Sanitize memo: remove non-printable chars except tab (0x09) and space */
static int sanitize_memo(const char *input, int input_len, char *output, int max_out) {
    int j = 0;
    for (int i = 0; i < input_len && j < max_out - 1; i++) {
        unsigned char ch = (unsigned char)input[i];
        /* Allow printable ASCII and horizontal tab */
        if (is_memo_printable(ch) || ch == 0x09) {
            output[j++] = (char)ch;
        }
    }
    output[j] = '\0';
    return j;
}

/* Build proxy response header with transaction metadata */
static int build_proxy_header(const Transaction *tx, char *header_buf, int buf_size) {
    char sanitized_memo[MAX_MEMO_LEN];
    int memo_len = sanitize_memo(tx->memo, tx->memo_len, sanitized_memo, MAX_MEMO_LEN);

    int written = snprintf(header_buf, buf_size,
        "X-Contract-Sender: %lu\r\n"
        "X-Contract-Receiver: %lu\r\n"
        "X-Contract-Amount: %lu\r\n"
        "X-Contract-Memo: %s\r\n",
        tx->sender, tx->receiver, tx->amount, sanitized_memo);

    return (written < buf_size) ? written : -1;
}

/* Encode memo using contract-specific percent encoding for proxy transport */
static int encode_memo_for_transport(const char *memo, int memo_len, char *out, int out_size) {
    int j = 0;
    for (int i = 0; i < memo_len && j < out_size - 4; i++) {
        unsigned char ch = (unsigned char)memo[i];
        /* Encode characters that could interfere with HTTP framing */
        if (ch == '%') {
            out[j++] = '%'; out[j++] = '2'; out[j++] = '5';
        } else if (ch == '\r') {
            out[j++] = '%'; out[j++] = '0'; out[j++] = 'D';
        } else if (ch == '\n') {
            out[j++] = '%'; out[j++] = '0'; out[j++] = 'A';
        } else {
            out[j++] = (char)ch;
        }
    }
    out[j] = '\0';
    return j;
}

/* Process transaction and generate proxy response */
int process_transaction(const Transaction *tx, ProxyResponse *resp) {
    if (!tx || !resp) return -1;

    memset(resp, 0, sizeof(ProxyResponse));

    /* Validate basic transaction fields */
    if (tx->amount == 0 || tx->sender == tx->receiver) {
        return -1;
    }

    /* Build response headers - memo goes through sanitize but NOT encode */
    resp->headers_len = build_proxy_header(tx, resp->headers, MAX_HEADER_LEN);
    if (resp->headers_len < 0) return -1;

    /* Build response body with encoded memo for logging */
    char encoded_memo[MAX_MEMO_LEN * 3];
    encode_memo_for_transport(tx->memo, tx->memo_len, encoded_memo, sizeof(encoded_memo));

    resp->body_len = snprintf(resp->body, sizeof(resp->body),
        "{\"status\":\"ok\",\"memo_encoded\":\"%s\"}", encoded_memo);

    return 0;
}

/* Reverse proxy forwarding - assembles final HTTP response */
int forward_to_client(int client_fd, const ProxyResponse *resp) {
    char final_response[2048];
    int offset = 0;

    offset += snprintf(final_response + offset, sizeof(final_response) - offset,
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %d\r\n", resp->body_len);

    /* Append contract-specific headers */
    memcpy(final_response + offset, resp->headers, resp->headers_len);
    offset += resp->headers_len;

    /* End of headers */
    memcpy(final_response + offset, "\r\n", 2);
    offset += 2;

    /* Append body */
    memcpy(final_response + offset, resp->body, resp->body_len);
    offset += resp->body_len;

    /* write(client_fd, final_response, offset); */
    return offset;
}

/* Entry point for contract execution */
int contract_main(const char *raw_tx_data, int data_len) {
    if (data_len < (int)sizeof(Transaction)) return -1;

    Transaction tx;
    memcpy(&tx, raw_tx_data, sizeof(Transaction));

    /* Clamp memo_len to prevent buffer overread */
    if (tx.memo_len > MAX_MEMO_LEN - 1) {
        tx.memo_len = MAX_MEMO_LEN - 1;
    }
    tx.memo[tx.memo_len] = '\0';

    ProxyResponse resp;
    if (process_transaction(&tx, &resp) != 0) {
        return -1;
    }

    return forward_to_client(1, &resp);
}
